<?php
require_once __DIR__.'/../config/bootstrap.php'; require_role('alumno');
$uid=(int)current_user()['id'];
$q=$pdo->prepare("SELECT m.*,c.nombre carrera FROM matriculas m JOIN carreras c ON c.id=m.carrera_id WHERE m.alumno_id=? AND m.estado='activa' LIMIT 1");$q->execute([$uid]);$enrollment=$q->fetch();
$unitFilter=(int)($_GET['unidad_id']??0);$from=$_GET['desde']??'';$to=$_GET['hasta']??'';
foreach(['desde','hasta'] as $key){$v=$key==='desde'?$from:$to;if($v!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)){if($key==='desde')$from='';else $to='';}}
$rows=[];$units=[];$attendance=[];$grades=[];
if($enrollment){$args=[$enrollment['carrera_id'],$enrollment['modulo_num'],$enrollment['ciclo_num']];$q=$pdo->prepare("SELECT DISTINCT u.id,u.nombre FROM unidades_didacticas u WHERE u.carrera_id=? AND u.modulo_num=? AND u.ciclo_num=? AND u.activa=1 ORDER BY u.nombre");$q->execute($args);$units=$q->fetchAll();
 $q=$pdo->prepare("SELECT h.*,u.nombre unidad,us.nombres,us.apellidos FROM horarios h JOIN unidades_didacticas u ON u.id=h.unidad_id JOIN usuarios us ON us.id=h.docente_id WHERE h.carrera_id=? AND h.modulo_num=? AND h.ciclo_num=? ORDER BY h.dia_semana,h.hora_inicio");$q->execute($args);$rows=$q->fetchAll();
 $sql="SELECT a.estado,p.fecha_clase,u.id unidad_id,u.nombre unidad FROM asistencias a JOIN plazos_registro p ON p.id=a.plazo_id JOIN unidades_didacticas u ON u.id=p.unidad_id WHERE a.alumno_id=? AND u.carrera_id=? AND u.modulo_num=? AND u.ciclo_num=?";$params=[$uid,$enrollment['carrera_id'],$enrollment['modulo_num'],$enrollment['ciclo_num']];if($unitFilter){$sql.=' AND u.id=?';$params[]=$unitFilter;}if($from!==''){$sql.=' AND p.fecha_clase>=?';$params[]=$from;}if($to!==''){$sql.=' AND p.fecha_clase<=?';$params[]=$to;}$sql.=' ORDER BY p.fecha_clase DESC';$q=$pdo->prepare($sql);$q->execute($params);$attendance=$q->fetchAll();
 $sql="SELECT c.concepto,c.nota,p.fecha_clase,u.id unidad_id,u.nombre unidad FROM calificaciones c JOIN plazos_registro p ON p.id=c.plazo_id JOIN unidades_didacticas u ON u.id=p.unidad_id WHERE c.alumno_id=? AND u.carrera_id=? AND u.modulo_num=? AND u.ciclo_num=?";$params=[$uid,$enrollment['carrera_id'],$enrollment['modulo_num'],$enrollment['ciclo_num']];if($unitFilter){$sql.=' AND u.id=?';$params[]=$unitFilter;}if($from!==''){$sql.=' AND p.fecha_clase>=?';$params[]=$from;}if($to!==''){$sql.=' AND p.fecha_clase<=?';$params[]=$to;}$sql.=' ORDER BY p.fecha_clase DESC,c.concepto';$q=$pdo->prepare($sql);$q->execute($params);$grades=$q->fetchAll();
 audit($pdo,$uid,'consulta_academica','Consulta de horario, asistencias y calificaciones');}
$pageTitle='Panel alumno';$assetPrefix='../';require __DIR__.'/../includes/header.php';
?>
<div class="dashboard-head"><div><div class="eyebrow">MI ESPACIO ACADÉMICO</div><h1>Hola, <?=h(current_user()['nombre']??'Alumno')?></h1><p class="muted">Consulta tus horarios, asistencias y calificaciones.</p></div><span class="status success">Alumno</span></div>
<?php if($enrollment):?><div class="stats-grid"><article class="stat-card"><span>Carrera</span><strong class="small-value"><?=h($enrollment['carrera'])?></strong></article><article class="stat-card"><span>Módulo</span><strong><?= (int)$enrollment['modulo_num']?></strong></article><article class="stat-card"><span>Ciclo</span><strong><?= (int)$enrollment['ciclo_num']?></strong></article></div><?php else:?><div class="alert warning">Tu cuenta todavía no tiene una matrícula activa. Contacta con administración.</div><?php endif;?>
<section class="panel"><h2>Mi horario y mis docentes</h2><?php if(!$rows):?><p class="muted">Aún no hay horarios publicados para tu grupo.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Día</th><th>Horario</th><th>Unidad didáctica</th><th>Docente</th><th>Aula</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h([1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'][(int)$r['dia_semana']]??'')?></td><td><?=h(substr($r['hora_inicio'],0,5).'–'.substr($r['hora_fin'],0,5))?></td><td><?=h($r['unidad'])?></td><td><?=h($r['nombres'].' '.$r['apellidos'])?></td><td><?=h($r['aula'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($enrollment):?><section class="panel"><h2>Consultar mis asistencias y notas</h2><form method="get" class="form-grid"><div class="field"><label for="unidad_id">Unidad didáctica</label><select name="unidad_id" id="unidad_id"><option value="0">Todas las unidades</option><?php foreach($units as $u):?><option value="<?=$u['id']?>" <?=(int)$u['id']===$unitFilter?'selected':''?>><?=h($u['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label for="desde">Desde</label><input type="date" name="desde" id="desde" value="<?=h($from)?>"></div><div class="field"><label for="hasta">Hasta</label><input type="date" name="hasta" id="hasta" value="<?=h($to)?>"></div><div class="field full"><button class="btn primary">Aplicar filtros</button> <a class="btn secondary" href="index.php">Limpiar</a></div></form></section>
<section class="panel"><h2>Mis asistencias</h2><?php if(!$attendance):?><p class="muted">No hay asistencias registradas para los filtros seleccionados.</p><?php else:$present=0;foreach($attendance as $a)if(in_array($a['estado'],['presente','tardanza'],true))$present++;$pct=count($attendance)?round($present/count($attendance)*100,1):0;?><p class="muted">Registros: <?=count($attendance)?> · Porcentaje de asistencia (presente + tardanza): <?=$pct?>%</p><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Unidad didáctica</th><th>Estado</th></tr></thead><tbody><?php foreach($attendance as $a):?><tr><td><?=h($a['fecha_clase'])?></td><td><?=h($a['unidad'])?></td><td><?=h(['presente'=>'Presente','ausente'=>'Falta','tardanza'=>'Tardanza'][$a['estado']]??$a['estado'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><h2>Mi récord de notas</h2><?php if(!$grades):?><p class="muted">Todavía no hay calificaciones registradas para los filtros seleccionados.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Unidad didáctica</th><th>Evaluación</th><th>Nota</th></tr></thead><tbody><?php foreach($grades as $g):?><tr><td><?=h($g['fecha_clase'])?></td><td><?=h($g['unidad'])?></td><td><?=h($g['concepto'])?></td><td><?=h($g['nota'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?>
<?php require __DIR__.'/../includes/footer.php';?>
